const UI="0.2.0-beta1",RAW="https://raw.githubusercontent.com/huoguotiankong/source-core-8d7/main/",CDN="https://cdn.jsdelivr.net/gh/huoguotiankong/source-core-8d7@main/";
function repo(p){const{source}=this;return String(source.get("repoLine")||"raw")==="cdn"?CDN+p:RAW+p}
function lineName(){const{source}=this;return String(source.get("repoLine")||"raw")==="cdn"?"jsDelivr":"GitHub Raw"}
function switchLine(){const{source,java}=this,n=String(source.get("repoLine")||"raw")==="raw"?"cdn":"raw";source.put("repoLine",n);java.longToast("已切换："+(n==="cdn"?"jsDelivr":"GitHub Raw")+"\n刷新分类后生效")}
function page(o){const{java}=this;return"data:application/json;base64,"+java.base64Encode(JSON.stringify(o))}
function esc(v){return String(v==null?"":v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}

